-- =============================================================================
--  FIRE CAT · Tienda online, fabricación y finanzas
--  Script completo de base de datos (MariaDB 10.4+ de XAMPP / MySQL 8.0+)
--
--  Importación: phpMyAdmin → pestaña "Importar" → seleccionar este archivo → Continuar.
--  El script crea la base de datos `tienda_ropa`, las 27 tablas (tienda, fabricación
--  y finanzas), relaciones, índices, una vista y los datos de prueba.
--
--  ATENCIÓN: el script ELIMINA la base de datos `tienda_ropa` si ya existe.
--
--  Credenciales de DESARROLLO (las contraseñas sólo se guardan como hash bcrypt
--  generado con password_hash(); nunca en texto plano):
--    Administrador : admin@firecat.com    / Admin123*    (se obliga a cambiarla
--                                                         en el primer inicio de sesión)
--    Cliente       : cliente@firecat.com  / Cliente123*
--    Clientes extra: andres@example.com, camila@example.com y 12 más / Cliente123*
-- =============================================================================

SET NAMES utf8mb4;
SET time_zone = '-05:00';
SET FOREIGN_KEY_CHECKS = 0;

DROP DATABASE IF EXISTS tienda_ropa;
CREATE DATABASE tienda_ropa CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tienda_ropa;

-- -----------------------------------------------------------------------------
-- 1. USUARIOS (clientes y administradores)
-- -----------------------------------------------------------------------------
CREATE TABLE usuarios (
    id                    INT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre                VARCHAR(60)  NOT NULL,
    apellido              VARCHAR(60)  NOT NULL,
    email                 VARCHAR(120) NOT NULL,
    password_hash         VARCHAR(255) NOT NULL,
    telefono              VARCHAR(20)  NULL,
    direccion             VARCHAR(160) NULL,
    ciudad                VARCHAR(80)  NULL,
    rol                   ENUM('administrador','cliente') NOT NULL DEFAULT 'cliente',
    estado                ENUM('activo','inactivo')       NOT NULL DEFAULT 'activo',
    debe_cambiar_password TINYINT(1)   NOT NULL DEFAULT 0,
    ultimo_acceso         DATETIME     NULL,
    fecha_registro        DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_usuarios_email (email),
    KEY idx_usuarios_rol_estado (rol, estado)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tokens de recuperación de contraseña (se guarda sólo el hash SHA-256 del token)
CREATE TABLE password_resets (
    id             INT UNSIGNED NOT NULL AUTO_INCREMENT,
    usuario_id     INT UNSIGNED NOT NULL,
    token_hash     CHAR(64)     NOT NULL,
    expira         DATETIME     NOT NULL,
    usado          TINYINT(1)   NOT NULL DEFAULT 0,
    fecha_creacion DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_password_resets_token (token_hash),
    KEY idx_password_resets_usuario (usuario_id),
    CONSTRAINT fk_password_resets_usuario FOREIGN KEY (usuario_id)
        REFERENCES usuarios (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Registro de intentos de inicio de sesión (limitación de fuerza bruta)
CREATE TABLE intentos_login (
    id     INT UNSIGNED NOT NULL AUTO_INCREMENT,
    email  VARCHAR(120) NOT NULL,
    ip     VARCHAR(45)  NOT NULL,
    exito  TINYINT(1)   NOT NULL DEFAULT 0,
    fecha  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_intentos_email_fecha (email, fecha),
    KEY idx_intentos_ip_fecha (ip, fecha)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 2. CATÁLOGO
-- -----------------------------------------------------------------------------
CREATE TABLE categorias (
    id             INT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre         VARCHAR(60)  NOT NULL,
    descripcion    VARCHAR(255) NULL,
    imagen         VARCHAR(255) NULL,
    estado         ENUM('activa','inactiva') NOT NULL DEFAULT 'activa',
    fecha_creacion DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_categorias_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Catálogos de atributos (normalización: una talla / un color se define una sola vez)
CREATE TABLE tallas (
    id     TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre VARCHAR(10)      NOT NULL,
    orden  TINYINT UNSIGNED NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    UNIQUE KEY uq_tallas_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE colores (
    id          TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre      VARCHAR(30)      NOT NULL,
    codigo_hex  CHAR(7)          NOT NULL DEFAULT '#000000',
    PRIMARY KEY (id),
    UNIQUE KEY uq_colores_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE productos (
    id                  INT UNSIGNED  NOT NULL AUTO_INCREMENT,
    categoria_id        INT UNSIGNED  NOT NULL,
    nombre              VARCHAR(120)  NOT NULL,
    descripcion         TEXT          NULL,
    precio              DECIMAL(10,2) NOT NULL,
    imagen              VARCHAR(255)  NULL,
    destacado           TINYINT(1)    NOT NULL DEFAULT 0,
    estado              ENUM('activo','inactivo') NOT NULL DEFAULT 'activo',
    fecha_creacion      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_productos_categoria (categoria_id),
    KEY idx_productos_estado (estado, destacado),
    KEY idx_productos_nombre (nombre),
    CONSTRAINT chk_productos_precio CHECK (precio > 0),
    CONSTRAINT fk_productos_categoria FOREIGN KEY (categoria_id)
        REFERENCES categorias (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Cada combinación producto + talla + color es una variante con su propio stock
CREATE TABLE variantes_producto (
    id                  INT UNSIGNED     NOT NULL AUTO_INCREMENT,
    producto_id         INT UNSIGNED     NOT NULL,
    talla_id            TINYINT UNSIGNED NOT NULL,
    color_id            TINYINT UNSIGNED NOT NULL,
    sku                 VARCHAR(40)      NOT NULL,
    stock               INT UNSIGNED     NOT NULL DEFAULT 0,
    estado              ENUM('activo','inactivo') NOT NULL DEFAULT 'activo',
    fecha_creacion      DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_variantes_combinacion (producto_id, talla_id, color_id),
    UNIQUE KEY uq_variantes_sku (sku),
    KEY idx_variantes_stock (stock),
    KEY idx_variantes_talla (talla_id),
    KEY idx_variantes_color (color_id),
    CONSTRAINT chk_variantes_stock CHECK (stock >= 0),
    CONSTRAINT fk_variantes_producto FOREIGN KEY (producto_id)
        REFERENCES productos (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_variantes_talla FOREIGN KEY (talla_id)
        REFERENCES tallas (id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_variantes_color FOREIGN KEY (color_id)
        REFERENCES colores (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 3. CARRITO (uno por usuario)
-- -----------------------------------------------------------------------------
CREATE TABLE carritos (
    id                  INT UNSIGNED NOT NULL AUTO_INCREMENT,
    usuario_id          INT UNSIGNED NOT NULL,
    fecha_creacion      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_carritos_usuario (usuario_id),
    CONSTRAINT fk_carritos_usuario FOREIGN KEY (usuario_id)
        REFERENCES usuarios (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- precio_unitario es sólo referencial: el servidor SIEMPRE recalcula con productos.precio
CREATE TABLE carrito_detalle (
    id              INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    carrito_id      INT UNSIGNED      NOT NULL,
    producto_id     INT UNSIGNED      NOT NULL,
    variante_id     INT UNSIGNED      NOT NULL,
    cantidad        SMALLINT UNSIGNED NOT NULL DEFAULT 1,
    precio_unitario DECIMAL(10,2)     NOT NULL,
    fecha_agregado  DATETIME          NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_carrito_variante (carrito_id, variante_id),
    KEY idx_carrito_detalle_producto (producto_id),
    KEY idx_carrito_detalle_variante (variante_id),
    CONSTRAINT chk_carrito_cantidad CHECK (cantidad > 0),
    CONSTRAINT fk_carrito_detalle_carrito FOREIGN KEY (carrito_id)
        REFERENCES carritos (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_carrito_detalle_producto FOREIGN KEY (producto_id)
        REFERENCES productos (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_carrito_detalle_variante FOREIGN KEY (variante_id)
        REFERENCES variantes_producto (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 4. PEDIDOS
-- -----------------------------------------------------------------------------
CREATE TABLE pedidos (
    id                  INT UNSIGNED  NOT NULL AUTO_INCREMENT,
    codigo              VARCHAR(20)   NULL,
    usuario_id          INT UNSIGNED  NOT NULL,
    subtotal            DECIMAL(12,2) NOT NULL,
    costo_envio         DECIMAL(10,2) NOT NULL DEFAULT 0,
    total               DECIMAL(12,2) NOT NULL,
    estado              ENUM('pendiente','confirmado','preparado','enviado','entregado','cancelado')
                        NOT NULL DEFAULT 'pendiente',
    metodo_pago         ENUM('contra_entrega','pedido_prueba') NOT NULL DEFAULT 'contra_entrega',
    pago_con            DECIMAL(12,2) NULL COMMENT 'Efectivo con el que pagará (para calcular el cambio)',
    nombre_destinatario VARCHAR(120)  NOT NULL,
    telefono_entrega    VARCHAR(20)   NOT NULL,
    direccion_entrega   VARCHAR(160)  NOT NULL,
    ciudad_entrega      VARCHAR(80)   NOT NULL,
    notas               VARCHAR(255)  NULL,
    fecha_pedido        DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_pedidos_codigo (codigo),
    KEY idx_pedidos_usuario (usuario_id),
    KEY idx_pedidos_estado_fecha (estado, fecha_pedido),
    KEY idx_pedidos_fecha (fecha_pedido),
    CONSTRAINT chk_pedidos_totales CHECK (subtotal >= 0 AND total >= 0 AND costo_envio >= 0),
    CONSTRAINT fk_pedidos_usuario FOREIGN KEY (usuario_id)
        REFERENCES usuarios (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Guarda una "foto" del producto al momento de la compra (precio histórico,
-- nombre, talla y color) para que cambios futuros no alteren pedidos antiguos.
CREATE TABLE pedido_detalle (
    id              INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    pedido_id       INT UNSIGNED      NOT NULL,
    producto_id     INT UNSIGNED      NOT NULL,
    variante_id     INT UNSIGNED      NOT NULL,
    nombre_producto VARCHAR(120)      NOT NULL,
    talla           VARCHAR(10)       NOT NULL,
    color           VARCHAR(30)       NOT NULL,
    cantidad        SMALLINT UNSIGNED NOT NULL,
    precio_unitario DECIMAL(10,2)     NOT NULL,
    costo_unitario  DECIMAL(12,2)     NULL COMMENT 'Costo de fabricación estimado al momento de la venta',
    subtotal        DECIMAL(12,2)     NOT NULL,
    PRIMARY KEY (id),
    KEY idx_pedido_detalle_pedido (pedido_id),
    KEY idx_pedido_detalle_producto (producto_id),
    KEY idx_pedido_detalle_variante (variante_id),
    CONSTRAINT chk_pedido_detalle CHECK (cantidad > 0 AND precio_unitario >= 0),
    CONSTRAINT fk_pedido_detalle_pedido FOREIGN KEY (pedido_id)
        REFERENCES pedidos (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_pedido_detalle_producto FOREIGN KEY (producto_id)
        REFERENCES productos (id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_pedido_detalle_variante FOREIGN KEY (variante_id)
        REFERENCES variantes_producto (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Trazabilidad de cambios de estado de cada pedido
CREATE TABLE pedido_historial (
    id              INT UNSIGNED NOT NULL AUTO_INCREMENT,
    pedido_id       INT UNSIGNED NOT NULL,
    estado_anterior VARCHAR(20)  NULL,
    estado_nuevo    VARCHAR(20)  NOT NULL,
    usuario_id      INT UNSIGNED NULL COMMENT 'Quién realizó el cambio',
    comentario      VARCHAR(255) NULL,
    fecha           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_pedido_historial_pedido (pedido_id),
    CONSTRAINT fk_pedido_historial_pedido FOREIGN KEY (pedido_id)
        REFERENCES pedidos (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_pedido_historial_usuario FOREIGN KEY (usuario_id)
        REFERENCES usuarios (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 5. FABRICACIÓN: proveedores, materias primas, compras, fichas técnicas y producción
-- -----------------------------------------------------------------------------
CREATE TABLE proveedores (
    id             INT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre         VARCHAR(120) NOT NULL,
    nit            VARCHAR(20)  NULL,
    contacto       VARCHAR(80)  NULL,
    telefono       VARCHAR(20)  NULL,
    email          VARCHAR(120) NULL,
    direccion      VARCHAR(160) NULL,
    ciudad         VARCHAR(80)  NULL,
    notas          VARCHAR(255) NULL,
    estado         ENUM('activo','inactivo') NOT NULL DEFAULT 'activo',
    fecha_creacion DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_proveedores_nombre (nombre),
    UNIQUE KEY uq_proveedores_nit (nit)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Telas, Hilos, Botones, Cierres, Etiquetas y empaque, Otros insumos
CREATE TABLE tipos_material (
    id     TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre VARCHAR(40)      NOT NULL,
    icono  VARCHAR(30)      NOT NULL DEFAULT 'bi-box',
    PRIMARY KEY (id),
    UNIQUE KEY uq_tipos_material_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Materias primas. costo_promedio = costo promedio ponderado (se recalcula en cada compra)
CREATE TABLE materiales (
    id                     INT UNSIGNED     NOT NULL AUTO_INCREMENT,
    tipo_id                TINYINT UNSIGNED NOT NULL,
    codigo                 VARCHAR(20)      NOT NULL,
    nombre                 VARCHAR(120)     NOT NULL,
    descripcion            VARCHAR(255)     NULL,
    unidad                 ENUM('metro','unidad','cono','kilogramo','litro','rollo','par') NOT NULL DEFAULT 'unidad',
    stock                  DECIMAL(12,3)    NOT NULL DEFAULT 0,
    stock_minimo           DECIMAL(12,3)    NOT NULL DEFAULT 0,
    costo_promedio         DECIMAL(12,2)    NOT NULL DEFAULT 0,
    proveedor_preferido_id INT UNSIGNED     NULL,
    estado                 ENUM('activo','inactivo') NOT NULL DEFAULT 'activo',
    fecha_creacion         DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion    DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_materiales_codigo (codigo),
    UNIQUE KEY uq_materiales_nombre (nombre),
    KEY idx_materiales_tipo (tipo_id),
    CONSTRAINT chk_materiales CHECK (stock >= 0 AND stock_minimo >= 0 AND costo_promedio >= 0),
    CONSTRAINT fk_materiales_tipo FOREIGN KEY (tipo_id)
        REFERENCES tipos_material (id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_materiales_proveedor FOREIGN KEY (proveedor_preferido_id)
        REFERENCES proveedores (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Compras de materiales a proveedores (cabecera + detalle)
CREATE TABLE compras_material (
    id             INT UNSIGNED  NOT NULL AUTO_INCREMENT,
    codigo         VARCHAR(20)   NULL,
    proveedor_id   INT UNSIGNED  NOT NULL,
    fecha          DATE          NOT NULL,
    numero_factura VARCHAR(40)   NULL,
    total          DECIMAL(14,2) NOT NULL DEFAULT 0,
    estado         ENUM('recibida','anulada') NOT NULL DEFAULT 'recibida',
    notas          VARCHAR(255)  NULL,
    usuario_id     INT UNSIGNED  NULL,
    fecha_creacion DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_compras_codigo (codigo),
    KEY idx_compras_fecha (fecha, estado),
    KEY idx_compras_proveedor (proveedor_id),
    CONSTRAINT chk_compras_total CHECK (total >= 0),
    CONSTRAINT fk_compras_proveedor FOREIGN KEY (proveedor_id)
        REFERENCES proveedores (id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_compras_usuario FOREIGN KEY (usuario_id)
        REFERENCES usuarios (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE compra_detalle (
    id             INT UNSIGNED  NOT NULL AUTO_INCREMENT,
    compra_id      INT UNSIGNED  NOT NULL,
    material_id    INT UNSIGNED  NOT NULL,
    cantidad       DECIMAL(12,3) NOT NULL,
    costo_unitario DECIMAL(12,2) NOT NULL,
    subtotal       DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (id),
    KEY idx_compra_detalle_compra (compra_id),
    KEY idx_compra_detalle_material (material_id),
    CONSTRAINT chk_compra_detalle CHECK (cantidad > 0 AND costo_unitario >= 0),
    CONSTRAINT fk_compra_detalle_compra FOREIGN KEY (compra_id)
        REFERENCES compras_material (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_compra_detalle_material FOREIGN KEY (material_id)
        REFERENCES materiales (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Ficha técnica (receta) de fabricación: una por producto
CREATE TABLE fichas_tecnicas (
    id                  INT UNSIGNED  NOT NULL AUTO_INCREMENT,
    producto_id         INT UNSIGNED  NOT NULL,
    costo_mano_obra     DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT 'Mano de obra directa por prenda',
    costos_indirectos   DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT 'Energía, depreciación, etc. por prenda',
    tiempo_minutos      SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    notas               VARCHAR(500)  NULL,
    fecha_actualizacion DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_fichas_producto (producto_id),
    CONSTRAINT chk_fichas CHECK (costo_mano_obra >= 0 AND costos_indirectos >= 0),
    CONSTRAINT fk_fichas_producto FOREIGN KEY (producto_id)
        REFERENCES productos (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Materiales que consume UNA prenda (+ % de merma o desperdicio)
CREATE TABLE ficha_materiales (
    id          INT UNSIGNED  NOT NULL AUTO_INCREMENT,
    ficha_id    INT UNSIGNED  NOT NULL,
    material_id INT UNSIGNED  NOT NULL,
    cantidad    DECIMAL(10,3) NOT NULL,
    merma_pct   DECIMAL(5,2)  NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    UNIQUE KEY uq_ficha_material (ficha_id, material_id),
    KEY idx_ficha_materiales_material (material_id),
    CONSTRAINT chk_ficha_materiales CHECK (cantidad > 0 AND merma_pct >= 0 AND merma_pct <= 100),
    CONSTRAINT fk_ficha_materiales_ficha FOREIGN KEY (ficha_id)
        REFERENCES fichas_tecnicas (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_ficha_materiales_material FOREIGN KEY (material_id)
        REFERENCES materiales (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Órdenes de producción: planificada → en_proceso (consume materiales) → terminada (suma prendas)
CREATE TABLE ordenes_produccion (
    id                INT UNSIGNED      NOT NULL AUTO_INCREMENT,
    codigo            VARCHAR(20)       NULL,
    producto_id       INT UNSIGNED      NOT NULL,
    variante_id       INT UNSIGNED      NOT NULL,
    cantidad          SMALLINT UNSIGNED NOT NULL,
    estado            ENUM('planificada','en_proceso','terminada','cancelada') NOT NULL DEFAULT 'planificada',
    costo_materiales  DECIMAL(14,2)     NOT NULL DEFAULT 0,
    costo_mano_obra   DECIMAL(14,2)     NOT NULL DEFAULT 0,
    costo_indirecto   DECIMAL(14,2)     NOT NULL DEFAULT 0,
    costo_total       DECIMAL(14,2)     NOT NULL DEFAULT 0,
    costo_unitario    DECIMAL(12,2)     NOT NULL DEFAULT 0,
    notas             VARCHAR(255)      NULL,
    usuario_id        INT UNSIGNED      NULL,
    fecha_creacion    DATETIME          NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_inicio      DATETIME          NULL,
    fecha_fin         DATETIME          NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_ordenes_codigo (codigo),
    KEY idx_ordenes_estado (estado, fecha_creacion),
    KEY idx_ordenes_producto (producto_id),
    CONSTRAINT chk_ordenes_cantidad CHECK (cantidad > 0),
    CONSTRAINT fk_ordenes_producto FOREIGN KEY (producto_id)
        REFERENCES productos (id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_ordenes_variante FOREIGN KEY (variante_id)
        REFERENCES variantes_producto (id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_ordenes_usuario FOREIGN KEY (usuario_id)
        REFERENCES usuarios (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Consumo REAL de materiales de cada orden (con el costo del momento)
CREATE TABLE produccion_consumos (
    id             INT UNSIGNED  NOT NULL AUTO_INCREMENT,
    orden_id       INT UNSIGNED  NOT NULL,
    material_id    INT UNSIGNED  NOT NULL,
    cantidad       DECIMAL(12,3) NOT NULL,
    costo_unitario DECIMAL(12,2) NOT NULL,
    subtotal       DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (id),
    KEY idx_consumos_orden (orden_id),
    KEY idx_consumos_material (material_id),
    CONSTRAINT fk_consumos_orden FOREIGN KEY (orden_id)
        REFERENCES ordenes_produccion (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_consumos_material FOREIGN KEY (material_id)
        REFERENCES materiales (id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Kardex de materias primas
CREATE TABLE movimientos_material (
    id               INT UNSIGNED  NOT NULL AUTO_INCREMENT,
    material_id      INT UNSIGNED  NOT NULL,
    tipo             ENUM('compra','consumo','ajuste','devolucion','anulacion') NOT NULL,
    cantidad         DECIMAL(12,3) NOT NULL COMMENT 'Positivo suma stock, negativo resta',
    stock_resultante DECIMAL(12,3) NOT NULL,
    costo_unitario   DECIMAL(12,2) NOT NULL DEFAULT 0,
    motivo           VARCHAR(255)  NULL,
    compra_id        INT UNSIGNED  NULL,
    orden_id         INT UNSIGNED  NULL,
    usuario_id       INT UNSIGNED  NULL,
    fecha            DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_mov_material_fecha (material_id, fecha),
    CONSTRAINT fk_mov_material_material FOREIGN KEY (material_id)
        REFERENCES materiales (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_mov_material_compra FOREIGN KEY (compra_id)
        REFERENCES compras_material (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_mov_material_orden FOREIGN KEY (orden_id)
        REFERENCES ordenes_produccion (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_mov_material_usuario FOREIGN KEY (usuario_id)
        REFERENCES usuarios (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 6. GASTOS operativos, de mantenimiento y otros
-- -----------------------------------------------------------------------------
CREATE TABLE categorias_gasto (
    id     TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre VARCHAR(60)      NOT NULL,
    grupo  ENUM('operativo','mantenimiento','otro') NOT NULL DEFAULT 'operativo',
    PRIMARY KEY (id),
    UNIQUE KEY uq_categorias_gasto_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE gastos (
    id             INT UNSIGNED     NOT NULL AUTO_INCREMENT,
    categoria_id   TINYINT UNSIGNED NOT NULL,
    descripcion    VARCHAR(160)     NOT NULL,
    monto          DECIMAL(14,2)    NOT NULL,
    fecha          DATE             NOT NULL,
    metodo_pago    ENUM('efectivo','transferencia','tarjeta') NOT NULL DEFAULT 'transferencia',
    proveedor_id   INT UNSIGNED     NULL,
    comprobante    VARCHAR(60)      NULL,
    usuario_id     INT UNSIGNED     NULL,
    fecha_creacion DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_gastos_fecha (fecha),
    KEY idx_gastos_categoria (categoria_id),
    CONSTRAINT chk_gastos_monto CHECK (monto > 0),
    CONSTRAINT fk_gastos_categoria FOREIGN KEY (categoria_id)
        REFERENCES categorias_gasto (id) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_gastos_proveedor FOREIGN KEY (proveedor_id)
        REFERENCES proveedores (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_gastos_usuario FOREIGN KEY (usuario_id)
        REFERENCES usuarios (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 7. INVENTARIO DE PRENDAS: kardex de movimientos por variante
-- -----------------------------------------------------------------------------
CREATE TABLE movimientos_inventario (
    id               INT UNSIGNED NOT NULL AUTO_INCREMENT,
    variante_id      INT UNSIGNED NOT NULL,
    tipo             ENUM('entrada','salida','ajuste','venta','devolucion','produccion') NOT NULL,
    cantidad         INT          NOT NULL COMMENT 'Positivo suma stock, negativo resta',
    stock_resultante INT UNSIGNED NOT NULL,
    motivo           VARCHAR(255) NULL,
    usuario_id       INT UNSIGNED NULL,
    pedido_id        INT UNSIGNED NULL,
    orden_id         INT UNSIGNED NULL COMMENT 'Orden de producción que originó la entrada',
    fecha            DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_movimientos_variante_fecha (variante_id, fecha),
    KEY idx_movimientos_pedido (pedido_id),
    CONSTRAINT fk_movimientos_variante FOREIGN KEY (variante_id)
        REFERENCES variantes_producto (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_movimientos_usuario FOREIGN KEY (usuario_id)
        REFERENCES usuarios (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_movimientos_pedido FOREIGN KEY (pedido_id)
        REFERENCES pedidos (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_movimientos_orden FOREIGN KEY (orden_id)
        REFERENCES ordenes_produccion (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 8. CONFIGURACIÓN de la tienda (clave → valor)
-- -----------------------------------------------------------------------------
CREATE TABLE configuracion (
    clave       VARCHAR(50)  NOT NULL,
    valor       VARCHAR(255) NOT NULL,
    descripcion VARCHAR(255) NULL,
    PRIMARY KEY (clave)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 9. VISTA de apoyo: stock total por producto
-- -----------------------------------------------------------------------------
CREATE VIEW vista_stock_productos AS
SELECT p.id                          AS producto_id,
       p.nombre                      AS producto,
       c.nombre                      AS categoria,
       p.precio,
       p.estado,
       COUNT(v.id)                   AS total_variantes,
       COALESCE(SUM(v.stock), 0)     AS stock_total
FROM productos p
JOIN categorias c           ON c.id = p.categoria_id
LEFT JOIN variantes_producto v ON v.producto_id = p.id AND v.estado = 'activo'
GROUP BY p.id, p.nombre, c.nombre, p.precio, p.estado;

SET FOREIGN_KEY_CHECKS = 1;

