-- Kardex: entrada inicial de todas las variantes (stock actual + unidades vendidas - unidades fabricadas)
SELECT v.id, 'entrada',
       v.stock + COALESCE(s.vendidas, 0) - COALESCE(f.fabricadas, 0),
       v.stock + COALESCE(s.vendidas, 0) - COALESCE(f.fabricadas, 0),
       'Inventario inicial', 1, DATE_SUB(NOW(), INTERVAL 95 DAY)
FROM variantes_producto v
LEFT JOIN (
    SELECT d.variante_id, SUM(d.cantidad) AS vendidas
    FROM pedido_detalle d JOIN pedidos p ON p.id = d.pedido_id
    WHERE p.estado <> 'cancelado'
    GROUP BY d.variante_id
) s ON s.variante_id = v.id
LEFT JOIN (
    SELECT variante_id, SUM(cantidad) AS fabricadas FROM ordenes_produccion WHERE estado = 'terminada' GROUP BY variante_id
) f ON f.variante_id = v.id;

-- Kardex: salidas por venta y devoluciones de pedidos cancelados (el saldo se calcula al final)
SELECT d.variante_id, 'venta', -d.cantidad, 0,
       CONCAT('Venta pedido ', p.codigo), p.usuario_id, p.id, p.fecha_pedido
FROM pedido_detalle d
JOIN pedidos p ON p.id = d.pedido_id
JOIN variantes_producto v ON v.id = d.variante_id;

SELECT d.variante_id, 'devolucion', d.cantidad, 0, CONCAT('Cancelación pedido ', p.codigo), p.usuario_id, p.id,
       p.fecha_pedido + INTERVAL 3 HOUR
FROM pedido_detalle d
JOIN pedidos p ON p.id = d.pedido_id
JOIN variantes_producto v ON v.id = d.variante_id
WHERE p.estado = 'cancelado';

-- Kardex: entradas de prendas por las órdenes de producción terminadas
SELECT o.variante_id, 'produccion', o.cantidad, 0, CONCAT('Producción ', o.codigo), 1, o.id, o.fecha_fin
FROM ordenes_produccion o JOIN variantes_producto v ON v.id = o.variante_id
WHERE o.estado = 'terminada';

-- Saldo (stock_resultante) de cada movimiento de prendas, recalculado en orden cronológico
UPDATE movimientos_inventario m
JOIN (SELECT id, SUM(cantidad) OVER (PARTITION BY variante_id ORDER BY fecha, id) AS saldo FROM movimientos_inventario) x ON x.id = m.id
SET m.stock_resultante = x.saldo;

